-- Staffing answer 522: the accounting export (Tally XML, Zoho Books CSV) of a month's issued invoices and credit notes
-- per GSTIN series. The formats are data (marked verify, for the CA to check against a real Tally import); the ledger
-- names, the GST split, TDS and round-off are company settings on 6.2. Rule sets only.
SELECT set_config('app.is_super_admin', 'on', true);

INSERT INTO "statutory_rule_sets" ("statute", "jurisdiction", "version", "valid_from", "values", "source", "verify") VALUES
  ('EXPORT.TALLY_XML', 'IN', '2026-v1', '2017-07-01',
   '{"voucherType":{"invoice":"Sales","credit_note":"Credit Note"},"dateFormat":"YYYYMMDD"}',
   'Tally Prime XML import (ENVELOPE / IMPORTDATA / TALLYMESSAGE / VOUCHER with ALLLEDGERENTRIES.LIST; debit amounts negative with ISDEEMEDPOSITIVE Yes). Voucher type names must exist in the company''s Tally; ledgers are created in Tally first. Verify with a real import before use.', true),
  ('EXPORT.ZOHO_CSV', 'IN', '2026-v1', '2017-07-01',
   '{"invoiceColumns":[{"header":"Invoice Date","field":"date"},{"header":"Invoice Number","field":"number"},{"header":"Invoice Status","field":"status"},{"header":"Customer Name","field":"customer"},{"header":"GST Treatment","field":"gstTreatment"},{"header":"GST Identification Number (GSTIN)","field":"gstin"},{"header":"Place of Supply","field":"placeOfSupply"},{"header":"Item Name","field":"item"},{"header":"Item Desc","field":"description"},{"header":"Quantity","field":"quantity"},{"header":"Item Price","field":"rate"},{"header":"SAC","field":"sac"},{"header":"Item Tax","field":"taxName"},{"header":"Item Tax %","field":"taxPct"},{"header":"Item Tax Amount","field":"taxAmount"},{"header":"Adjustment","field":"adjustment"},{"header":"Adjustment Description","field":"adjustmentDescription"},{"header":"TDS Name","field":"tdsName"},{"header":"TDS Amount","field":"tdsAmount"},{"header":"Total","field":"total"}],"creditNoteColumns":[{"header":"Credit Note Date","field":"date"},{"header":"Credit Note Number","field":"number"},{"header":"Reference Invoice","field":"original"},{"header":"Reason","field":"reason"},{"header":"Customer Name","field":"customer"},{"header":"GST Treatment","field":"gstTreatment"},{"header":"GST Identification Number (GSTIN)","field":"gstin"},{"header":"Place of Supply","field":"placeOfSupply"},{"header":"Item Desc","field":"description"},{"header":"Quantity","field":"quantity"},{"header":"Item Price","field":"rate"},{"header":"SAC","field":"sac"},{"header":"Item Tax","field":"taxName"},{"header":"Item Tax %","field":"taxPct"},{"header":"Item Tax Amount","field":"taxAmount"},{"header":"Adjustment","field":"adjustment"},{"header":"Total","field":"total"}]}',
   'Zoho Books (India) invoice and credit note import columns. Zoho imports invoices and credit notes as separate files; tax names must match the tax rates set up in Zoho. Verify with a real import before use.', true);
